import { TALENTS, DAILY_CHALLENGES } from './content.js';

export const SAVE_KEY = 'xiyou-survivor-save-v1';
export const CHAPTER_NAMES = ['东土启程','山川收徒','佛门试心','降魔伏怪','水国奇缘','真假心猿','狮驼险途','天竺寻真','灵山功成'];
export function dayKey(now=new Date()){ return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`; }
export function newSave(){return {version:1,unlockedStage:1,talents:{},talentPoints:0,bestScore:0,wins:0,runs:0,streak:0,scrolls:0,totalKills:0,lastRun:null,muted:false,volume:.65,quality:'auto',daily:{day:dayKey(),progress:{},claimed:[]},records:{},seenArtifacts:[],patrolSince:0,claimedChapters:[],tutorialSeen:false};}
export function sanitizeSave(value){const s={...newSave(),...(value&&typeof value==='object'?value:{})};for(const key of ['unlockedStage','talentPoints','bestScore','wins','runs','streak','scrolls','totalKills'])s[key]=Math.max(key==='unlockedStage'?1:0,Math.floor(Number(s[key])||0));s.unlockedStage=Math.min(81,s.unlockedStage);s.talents={...(s.talents||{})};for(const t of TALENTS)s.talents[t.id]=Math.min(t.maxLevel,Math.max(0,Math.floor(Number(s.talents[t.id])||0)));s.volume=Math.min(1,Math.max(0,Number(s.volume)||0));s.muted=!!s.muted;s.quality=['auto','high','low'].includes(s.quality)?s.quality:'auto';s.records=s.records&&typeof s.records==='object'?s.records:{};s.seenArtifacts=Array.isArray(s.seenArtifacts)?s.seenArtifacts:[];s.patrolSince=Number(s.patrolSince)>0?Number(s.patrolSince):Date.now();s.claimedChapters=Array.isArray(s.claimedChapters)?[...new Set(s.claimedChapters.map(Number).filter(n=>n>=1&&n<=9))]:[];refreshDaily(s);return s;}
export function refreshDaily(save,now=new Date()){const day=dayKey(now);if(!save.daily||save.daily.day!==day)save.daily={day,progress:{},claimed:[]};save.daily.progress=save.daily.progress||{};save.daily.claimed=Array.isArray(save.daily.claimed)?save.daily.claimed:[];return save.daily;}
export function talentCost(save,id){const t=TALENTS.find(t=>t.id===id);return t?t.baseCost*((save.talents[id]||0)+1):Infinity;}
export function buyTalent(save,id){const t=TALENTS.find(t=>t.id===id);if(!t)return {ok:false,message:'未知经脉'};const lv=save.talents[id]||0,cost=talentCost(save,id);if(lv>=t.maxLevel)return {ok:false,message:'此经脉已圆满'};if(save.talentPoints<cost)return {ok:false,message:'悟性不足，闯关与每日禅试可获取'};save.talentPoints-=cost;save.talents[id]=lv+1;return {ok:true,message:`${t.name}提升至${lv+1}级`};}
export function dailyRows(save){refreshDaily(save);return DAILY_CHALLENGES.map(c=>({...c,progress:Math.min(c.target,save.daily.progress[c.id]||0),claimed:save.daily.claimed.includes(c.id),complete:(save.daily.progress[c.id]||0)>=c.target}));}
export function claimDaily(save,id){const c=dailyRows(save).find(c=>c.id===id);if(!c||!c.complete||c.claimed)return {ok:false,message:c?.claimed?'今日已经领取':'达成目标后再来领取'};save.talentPoints+=c.reward;save.daily.claimed.push(id);return {ok:true,message:`悟性 +${c.reward}`};}
export function recordRun(save,state,stats={}){refreshDaily(save);const won=state.status==='won',score=state.kills*10+state.player.level*100+(won?1000:0),reward=Math.max(12,Math.floor(state.kills*.16))+Math.floor(state.time/30)+(won?80:0);save.runs++;save.totalKills+=state.kills;save.bestScore=Math.max(save.bestScore,score);save.talentPoints+=reward;save.lastRun={stageId:state.stage.id,characterId:state.character.id,characterName:state.character.name,stageName:state.stage.name,time:Math.floor(state.time),kills:state.kills,won};if(won){save.wins++;save.streak++;save.scrolls++;if(state.stage.id===save.unlockedStage)save.unlockedStage=Math.min(81,save.unlockedStage+1);}else save.streak=0;const record=save.records[state.stage.id]||{wins:0,bestScore:0};record.bestScore=Math.max(record.bestScore,score);record.wins+=(won?1:0);save.records[state.stage.id]=record;for(const skill of state.skills)if(!skill.isWeapon&&!save.seenArtifacts.includes(skill.id))save.seenArtifacts.push(skill.id);const p=save.daily.progress;p['daily-kills']=Math.max(p['daily-kills']||0,state.kills);p['daily-elite']=Math.max(p['daily-elite']||0,stats.elites||0);if(won){p['daily-stage']=1;if(!(stats.dashes||0))p['daily-no-dash']=1;}return {reward,score,won};}
// Patrol （巡山遣使）: idle earnings that accrue in real time between
// sessions, a meta staple of survivors-like peers. The hourly rate grows
// with the highest unlocked stage and accrual caps at 8 hours, so coming
// back daily pays better than leaving it for a week.
export const PATROL_CAP_MS=8*3600*1000;
export function patrolRatePerHour(save){return 20+save.unlockedStage;}
export function patrolAccrued(save,now=Date.now()){const elapsed=Math.min(PATROL_CAP_MS,Math.max(0,now-(save.patrolSince||now)));return {ms:elapsed,amount:Math.floor(elapsed/60000*patrolRatePerHour(save)/60),capped:now-(save.patrolSince||now)>=PATROL_CAP_MS};}
export function claimPatrol(save,now=Date.now()){const {amount}=patrolAccrued(save,now);if(amount<=0)return {ok:false,message:'巡山刚出发，过一会儿再来'};save.talentPoints+=amount;save.patrolSince=now;return {ok:true,message:`巡山归来，悟性 +${amount}`,amount};}
// Chapter rewards: clearing all nine trials of a chapter pays out once,
// which also gives 经文 a second source beyond single-stage clears.
export function chapterComplete(save,chapter){const start=chapter*9+1;for(let id=start;id<start+9;id++)if(!(save.records[id]?.wins>0))return false;return true;}
export function chapterReward(chapter){return {talentPoints:300+chapter*50,scrolls:1};}
export function claimChapter(save,chapter){if(save.claimedChapters.includes(chapter))return {ok:false,message:'本章奖励已领取'};if(!chapterComplete(save,chapter))return {ok:false,message:'通关本章全部九难后领取'};const r=chapterReward(chapter);save.talentPoints+=r.talentPoints;save.scrolls+=r.scrolls;save.claimedChapters.push(chapter);return {ok:true,message:`章节奖励：悟性 +${r.talentPoints} · 经文 +${r.scrolls}`};}

